import (
	"context"
	"errors"
	"io"
	"log/slog"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// entry is a job with its enqueue position, so Pending can list jobs in order.
type entry struct {
	seq uint64
	job Job
}

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan entry
	workers int
	log     *slog.Logger

	ctx    context.Context    // passed to every job; cancelled by Shutdown
	cancel context.CancelFunc //
	wg     sync.WaitGroup     // the workers
	done   chan struct{}      // closed when the first Shutdown has finished

	mu       sync.Mutex
	closed   bool                // set by Shutdown; no job starts and no job is queued after it
	seq      uint64              // enqueue position of the next job
	waiting  map[uint64]entry    // queued jobs that have not started
	canceled []entry             // started jobs that Shutdown cancelled and that returned an error
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	ctx, cancel := context.WithCancel(context.Background())
	return &Runner{
		queue:   make(chan entry, queueSize),
		workers: workers,
		log:     log,
		ctx:     ctx,
		cancel:  cancel,
		done:    make(chan struct{}),
		waiting: map[uint64]entry{},
	}
}

// Start starts the workers. Workers started after Shutdown exit at once.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.wg.Done()
	for e := range r.queue {
		r.mu.Lock()
		if r.closed {
			// Not started: it stays in waiting and Pending returns it.
			r.mu.Unlock()
			continue
		}
		delete(r.waiting, e.seq)
		r.mu.Unlock()

		err := r.run(e.job)
		if err != nil {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
			if r.ctx.Err() != nil {
				r.mu.Lock()
				r.canceled = append(r.canceled, e)
				r.mu.Unlock()
			}
		}
	}
}

// run calls the job and turns a panic into a logged error, so the worker goes on with the next job.
func (r *Runner) run(j Job) (err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p)
			err = nil
		}
	}()
	return j.Run(r.ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped after Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	e := entry{seq: r.seq, job: j}
	select {
	case r.queue <- e:
		r.seq++
		r.waiting[e.seq] = e
		return nil
	default:
		return ErrQueueFull
	}
}

// Shutdown stops the runner: Enqueue refuses new jobs and jobs that have not started are not started.
// It waits for running jobs to finish. If ctx ends first, it cancels the context of every running job,
// waits for them to return and returns ctx.Err(). Otherwise it returns nil. Once it returns, none of the
// runner's goroutines is left. Later calls wait for the first call to finish and return nil.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		<-r.done
		return nil
	}
	r.closed = true
	close(r.queue)
	r.mu.Unlock()

	finished := make(chan struct{})
	go func() {
		r.wg.Wait()
		close(finished)
	}()

	var err error
	select {
	case <-finished:
	default:
		select {
		case <-finished:
		case <-ctx.Done():
			err = ctx.Err()
			r.cancel()
			<-finished
		}
	}
	r.cancel()
	close(r.done)
	return err
}

// Stop shuts the runner down, waiting up to 30 seconds for running jobs. See Shutdown.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued
// jobs that have not started. After Shutdown they are the jobs that were never started, followed by the
// jobs that Shutdown cancelled and that returned an error. A panicked job is not returned.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	waiting := make([]entry, 0, len(r.waiting))
	for _, e := range r.waiting {
		waiting = append(waiting, e)
	}
	sortEntries(waiting)
	canceled := append([]entry(nil), r.canceled...)
	sortEntries(canceled)

	jobs := make([]Job, 0, len(waiting)+len(canceled))
	for _, e := range append(waiting, canceled...) {
		jobs = append(jobs, e.job)
	}
	return jobs
}

func sortEntries(es []entry) {
	sort.Slice(es, func(i, j int) bool { return es[i].seq < es[j].seq })
}

