// Package jobs runs background work (renewals, webhook deliveries, emails) on a fixed number of workers.
package jobs

import (
	"context"
	"errors"
	"io"
	"log/slog"
	"sort"
	"sync"
	"time"
)

// Job is one piece of background work.
type Job struct {
	Name string
	Run  func(ctx context.Context) error
}

// ErrQueueFull is returned by Enqueue when the queue has no room.
var ErrQueueFull = errors.New("the job queue is full")

// ErrStopped is returned by Enqueue once Shutdown has been called.
var ErrStopped = errors.New("the job runner is stopped")

// stopTimeout is how long Stop waits for running jobs before cancelling them.
const stopTimeout = 30 * time.Second

// entry is a job with its enqueue position, so Pending can list jobs in order.
type entry struct {
	seq uint64
	job Job
}

// Runner runs jobs on its workers.
type Runner struct {
	queue   chan entry
	workers int
	log     *slog.Logger

	ctx    context.Context    // passed to every job; cancelled by Shutdown
	cancel context.CancelFunc // cancels ctx
	exited chan struct{}      // each worker sends once as it returns
	done   chan struct{}      // closed when the first Shutdown has finished

	mu       sync.Mutex
	started  int              // workers started
	closed   bool             // set by Shutdown: no job starts and none is queued after it
	seq      uint64           // enqueue position of the next job
	waiting  map[uint64]entry // queued jobs that have not started
	canceled []entry          // started jobs that Shutdown cancelled and that returned an error
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	ctx, cancel := context.WithCancel(context.Background())
	return &Runner{
		queue:   make(chan entry, queueSize),
		workers: workers,
		log:     log,
		ctx:     ctx,
		cancel:  cancel,
		exited:  make(chan struct{}),
		done:    make(chan struct{}),
		waiting: map[uint64]entry{},
	}
}

// Start starts the workers. Workers started after Shutdown exit at once.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	for i := 0; i < r.workers; i++ {
		r.started++
		go r.work()
	}
}

func (r *Runner) work() {
	defer func() { r.exited <- struct{}{} }()
	for e := range r.queue {
		r.mu.Lock()
		if r.closed {
			// Not started: it stays in waiting and Pending returns it.
			r.mu.Unlock()
			continue
		}
		delete(r.waiting, e.seq)
		r.mu.Unlock()

		err := r.run(e.job)
		if err != nil {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
			if r.ctx.Err() != nil {
				r.mu.Lock()
				r.canceled = append(r.canceled, e)
				r.mu.Unlock()
			}
		}
	}
}

// run calls the job and turns a panic into a logged error, so the worker goes on with the next job.
func (r *Runner) run(j Job) (err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p)
			err = nil
		}
	}()
	return j.Run(r.ctx)
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped after Shutdown has been called.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	e := entry{seq: r.seq, job: j}
	select {
	case r.queue <- e:
		r.seq++
		r.waiting[e.seq] = e
		return nil
	default:
		return ErrQueueFull
	}
}

// Shutdown stops the runner: Enqueue refuses new jobs and jobs that have not started are not started.
// It waits for running jobs to finish. If ctx ends first, it cancels the context of every running job,
// waits for them to return and returns ctx.Err(). Otherwise it returns nil. Once it returns, none of the
// runner's goroutines is left. Later calls wait for the first call to finish and return nil.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		// Wait for the first call to finish, but not past ctx.
		select {
		case <-r.done:
			return nil
		default:
		}
		select {
		case <-r.done:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	r.closed = true
	close(r.queue)
	n := r.started
	r.mu.Unlock()

	var err error
	for i := 0; i < n; i++ {
		select {
		case <-r.exited:
			continue
		case <-ctx.Done():
		}
		// ctx ended first: cancel the running jobs and wait for every worker to return.
		err = ctx.Err()
		r.cancel()
		for ; i < n; i++ {
			<-r.exited
		}
	}
	r.cancel()
	close(r.done)
	return err
}

// Stop shuts the runner down, waiting up to 30 seconds for running jobs. See Shutdown.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), stopTimeout)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in enqueue order. Before Shutdown these are the queued
// jobs that have not started. After Shutdown they are the jobs that were never started, followed by the
// jobs that Shutdown cancelled and that returned an error. A panicked job is not returned.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	waiting := make([]entry, 0, len(r.waiting))
	for _, e := range r.waiting {
		waiting = append(waiting, e)
	}
	sortEntries(waiting)
	canceled := append([]entry(nil), r.canceled...)
	sortEntries(canceled)

	jobs := make([]Job, 0, len(waiting)+len(canceled))
	for _, e := range append(waiting, canceled...) {
		jobs = append(jobs, e.job)
	}
	return jobs
}

func sortEntries(es []entry) {
	sort.Slice(es, func(i, j int) bool { return es[i].seq < es[j].seq })
}
// Command tally runs the Tally API with the demo payment gateway, keeping its data in a snapshot file.
//
//	tally -addr :8080 -data tally.json
package main

import (
	"context"
	"errors"
	"flag"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"example.com/tally/internal/api"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/jobs"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/snapshot"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

func main() {
	addr := flag.String("addr", ":8080", "address to listen on")
	data := flag.String("data", "tally.json", "snapshot file (created when missing)")
	flag.Parse()
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	clk := clock.Real{}

	st, err := snapshot.Load(*data)
	switch {
	case errors.Is(err, os.ErrNotExist):
		st = store.New()
		if err := seed(st, clk.Now(), log); err != nil {
			log.Error("seed", "err", err)
			os.Exit(1)
		}
	case err != nil:
		log.Error("load snapshot", "err", err)
		os.Exit(1)
	}

	hooks := webhooks.New(webhooks.Options{Store: st, Clock: clk})
	pay := &payments.Service{Store: st, Gateway: &payments.Fake{}, Clock: clk, Publisher: hooks}
	subs := &subscriptions.Service{Store: st, Payments: pay, Clock: clk, Publisher: hooks}
	srv := api.New(st, api.Options{Clock: clk, Payments: pay, Subscriptions: subs, Webhooks: hooks, Mail: &mail.Outbox{Log: log}, Logger: log})

	runner := jobs.NewRunner(4, 100, log)
	runner.Start()
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		t := time.NewTicker(30 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-t.C:
				_ = runner.Enqueue(jobs.Job{Name: "renewals", Run: func(ctx context.Context) error { _, err := subs.RenewDue(ctx); return err }})
				_ = runner.Enqueue(jobs.Job{Name: "webhooks", Run: func(ctx context.Context) error { _, err := hooks.RunDue(ctx); return err }})
			}
		}
	}()

	hs := &http.Server{Addr: *addr, Handler: srv, ReadHeaderTimeout: 10 * time.Second}
	go func() {
		log.Info("listening", "addr", *addr)
		if err := hs.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("serve", "err", err)
			stop()
		}
	}()
	<-ctx.Done()
	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = hs.Shutdown(shutdown)
	// The signal context is already done, so the runner gets its own deadline.
	runnerCtx, cancelRunner := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancelRunner()
	if err := runner.Shutdown(runnerCtx); err != nil {
		log.Warn("jobs cancelled at shutdown", "err", err, "pending", len(runner.Pending()))
	}
	if err := snapshot.Save(st, *data, clk.Now()); err != nil {
		log.Error("save snapshot", "err", err)
		os.Exit(1)
	}
}

// seed adds a demo organization with an owner and prints the owner's API key.
func seed(st *store.Store, now time.Time, log *slog.Logger) error {
	o, err := st.CreateOrg("Demo Co", store.OrgTeam, "UTC", 0, now)
	if err != nil {
		return err
	}
	u, err := st.CreateUser("owner@demo.example", "Demo Owner", now)
	if err != nil {
		return err
	}
	if _, err := st.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		return err
	}
	k, err := st.CreateAPIKey(o.ID, u.ID, "Demo key", now)
	if err != nil {
		return err
	}
	log.Info("demo organization created", "org", o.ID, "api_key", k.Token)
	return nil
}

