	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error { panic("boom") }}); err != nil {
		t.Fatal(err)
	}
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("the job after a panic did not run")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	if p := r.Pending(); len(p) != 0 {
		t.Fatalf("pending = %v, want the panicked job not retried", names(p))
	}
}

func TestSecondShutdownHonorsItsContext(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	// "stuck" ignores cancellation until release is closed.
	if err := r.Enqueue(Job{Name: "stuck", Run: func(context.Context) error {
		close(started)
		<-release
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started

	firstErr := make(chan error, 1)
	go func() { firstErr <- r.Shutdown(context.Background()) }()
	waitClosed(t, r)

	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	secondErr := make(chan error, 1)
	go func() { secondErr <- r.Shutdown(ctx) }()
	select {
	case err := <-secondErr:
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("second Shutdown = %v, want DeadlineExceeded", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("second Shutdown did not return within its context")
	}

	// The first call is still waiting for the stuck job; it returns once the job does.
	select {
	case err := <-firstErr:
		t.Fatalf("first Shutdown returned early: %v", err)
	default:
	}
	close(release)
	if err := <-firstErr; err != nil {
		t.Fatalf("first Shutdown = %v, want nil", err)
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatalf("Shutdown after the first finished = %v, want nil", err)
	}
}

