func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		// Wait for the first call to finish, but not past ctx.
		select {
		case <-r.done:
			return nil
		default:
		}
		select {
		case <-r.done:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	r.closed = true
	close(r.queue)
	n := r.started
	r.mu.Unlock()

